package cgen_test

import (
	"go/ast"
	"go/parser"
	"go/token"
	"os"
	"path/filepath"
	"reflect"
	"regexp"
	"sort"
	"strconv"
	"strings"
	"testing"

	"github.com/szTheory/schway/internal/compiler/exitcode"
	"github.com/szTheory/schway/internal/compiler/testsupport"
)

// TestEmittedCExitLiteralsMatchTable pins the exit statuses baked into the
// generated C text (D-21) against the exitcode table. It scans cgen's string
// literals and never calls the emitters, so generated bytes stay untouched.
func TestEmittedCExitLiteralsMatchTable(t *testing.T) {
	const childWriteFailure = 74 // opaque generated-child status, not a host exitcode

	exitRE := regexp.MustCompile(`exit\((\d+)\)`)
	returnRE := regexp.MustCompile(`return (\d+);`)
	dir := testsupport.ProjectPath("internal", "compiler", "cgen")
	entries, err := os.ReadDir(dir)
	if err != nil {
		t.Fatal(err)
	}
	exitCounts := map[int]int{}
	returnSet := map[int]bool{}
	for _, entry := range entries {
		name := entry.Name()
		if entry.IsDir() || !strings.HasSuffix(name, ".go") || strings.HasSuffix(name, "_test.go") {
			continue
		}
		fset := token.NewFileSet()
		file, err := parser.ParseFile(fset, filepath.Join(dir, name), nil, 0)
		if err != nil {
			t.Fatal(err)
		}
		ast.Inspect(file, func(node ast.Node) bool {
			lit, ok := node.(*ast.BasicLit)
			if !ok || lit.Kind != token.STRING {
				return true
			}
			text, err := strconv.Unquote(lit.Value)
			if err != nil {
				return true
			}
			for _, match := range exitRE.FindAllStringSubmatch(text, -1) {
				value, _ := strconv.Atoi(match[1])
				exitCounts[value]++
			}
			for _, match := range returnRE.FindAllStringSubmatch(text, -1) {
				value, _ := strconv.Atoi(match[1])
				returnSet[value] = true
			}
			return true
		})
	}
	var gotExit []int
	for value := range exitCounts {
		gotExit = append(gotExit, value)
	}
	sort.Ints(gotExit)
	wantExit := []int{exitcode.Success, exitcode.AppInputRefused, exitcode.EventCapacity, childWriteFailure}
	if !reflect.DeepEqual(gotExit, wantExit) {
		t.Fatalf("distinct exit(N) values = %v, want %v", gotExit, wantExit)
	}
	if exitCounts[exitcode.AppInputRefused] < 1 || exitCounts[exitcode.EventCapacity] < 1 || exitCounts[childWriteFailure] < 1 {
		t.Fatalf("exit(65) count %d, exit(69) count %d, and opaque child write-failure exit(74) count %d must each be at least 1", exitCounts[exitcode.AppInputRefused], exitCounts[exitcode.EventCapacity], exitCounts[childWriteFailure])
	}
	// Generated-program child statuses; those outside the host table are
	// opaque child codes the host only passes through (28-01 inventory).
	returnMeaning := map[int]string{
		0:                        "success",
		1:                        "generic failure",
		2:                        "UseError.UnsupportedByte path",
		exitcode.Usage:           "wrong argument count or over-long argument",
		exitcode.AppInputRefused: "application refusal",
		70:                       "entry name missing",
		71:                       "unreachable after schway_defect",
		childWriteFailure:        "write failure",
	}
	var gotReturn, wantReturn []int
	for value := range returnSet {
		gotReturn = append(gotReturn, value)
	}
	for value := range returnMeaning {
		wantReturn = append(wantReturn, value)
	}
	sort.Ints(gotReturn)
	sort.Ints(wantReturn)
	if !reflect.DeepEqual(gotReturn, wantReturn) {
		t.Fatalf("distinct return N; values = %v, want %v", gotReturn, wantReturn)
	}
}
